RULES_FALLBACK_NET = ("-a always,exit -F arch=b64 -S connect -F saddr_fam=2 -k net\n"
                      "-a always,exit -F arch=b64 -S connect -F saddr_fam=10 -k net",
                      "-a always,exit -F arch=b64 -S connect -k net")
PERSIST_SYSTEM = ("/etc/crontab", "/etc/cron.d/", "/etc/cron.hourly/", "/etc/cron.daily/", "/var/spool/cron/",
                  "/etc/systemd/system/", "/etc/ld.so.preload", "/etc/profile.d/", "/etc/xdg/autostart/",
                  "/etc/sudoers.d/", "/etc/rc.local", "/etc/environment")
