class Runner:
    def __init__(self, dry):
        self.dry = dry

    def say(self, msg=""):
        print(msg, flush=True)

    def head(self, title):
        self.say(f"\n== {title}")

    def act(self, cmd, quiet=False):
        self.say("  $ " + " ".join(c if re.fullmatch(r"[\w@%+=:,./-]+", c) else repr(c) for c in cmd))
        if self.dry:
            return 0, ""
        rc, out = util.run(cmd, timeout=600)
        if rc != 0 and not quiet:
            self.say(f"    ! exit {rc}: {out.strip()[:400]}")
        return rc, out

    def write(self, path, content, mode=0o644):
        path = Path(path)
        old = path.read_text(errors="replace") if path.exists() else None
        if old == content:
            self.say(f"  = {path} already up to date")
            return False
        self.say(f"  > write {path}" + (" (previous version kept as .noxy-bak)" if old is not None else ""))
        if self.dry:
            for line in content.rstrip("\n").splitlines():
                self.say(f"      {line}")
            return True
        path.parent.mkdir(parents=True, exist_ok=True)
        if old is not None and not Path(str(path) + ".noxy-bak").exists():
            shutil.copy2(path, str(path) + ".noxy-bak")
        tmp = Path(str(path) + ".noxy-tmp")
        tmp.write_text(content)
        os.chmod(tmp, mode)
        os.replace(tmp, path)
        return True


def target_user(name=None):
    name = name or os.environ.get("SUDO_USER") or pwd.getpwuid(os.getuid()).pw_name
    return pwd.getpwnam(name)


def audit_rules(home, check_exists=True):
    """Watches only for paths that exist: auditctl stops loading a rules file at the first failing line."""
    lines = []
    for p in PERSIST_SYSTEM:
        if not check_exists or os.path.exists(p):
            lines.append(f"-w {p} -p wa -k persist")
    for p in PERSIST_HOME:
        full = os.path.join(home, p)
        if check_exists and not os.path.exists(full):
            continue
        perm = "rwa" if p == ".ssh/" else "wa"
        lines.append(f"-w {full} -p {perm} -k persist")
    return RULES.format(persist="\n".join(lines), home=home)


def set_conf(text, key, value):
    if re.search(rf"(?m)^\s*{re.escape(key)}\s*=", text):
        return re.sub(rf"(?m)^\s*{re.escape(key)}\s*=.*$", f"{key} = {value}", text)
    return text.rstrip("\n") + f"\n{key} = {value}\n"


def lab(dry=False, user=None, port=util.DEFAULT_PORT):
    r = Runner(dry)
    if os.geteuid() != 0 and not dry:
        sys.exit("`setup lab` changes system settings: run it with sudo (or add --dry-run to preview).")
    u = target_user(user)
    if u.pw_uid == 0:
        sys.exit("Run it with sudo from your own account (e.g. analyst), not from a root shell.")
    home = u.pw_dir
    r.say(f"noxy setup lab for user {u.pw_name} ({home})" + (" [dry run]" if dry else ""))

    r.head("Group: noxy (read access to audit logs and captures, nothing else)")
    try:
        grp.getgrnam(GROUP)
        r.say(f"  = group {GROUP} exists")
    except KeyError:
        r.act(["groupadd", "--system", GROUP])
    members = [] if dry else grp.getgrnam(GROUP).gr_mem
    if u.pw_name not in members:
        r.act(["usermod", "-aG", GROUP, u.pw_name])

    r.head("Packages: auditd, tcpdump")
    missing = [p for p, b in (("auditd", "auditctl"), ("tcpdump", "tcpdump")) if not shutil.which(b)]
    if missing:
        r.act(["apt-get", "install", "-y"] + missing + (["audispd-plugins"] if "auditd" in missing else []))
    else:
        r.say("  = installed")

    r.head("Time zone: UTC")
    r.act(["timedatectl", "set-timezone", "Etc/UTC"])

    r.head("Audit rules: executions, connections, persistence, editor settings")
    for sub in (".config/systemd/user", ".config/autostart", ".ssh", ".config/Code/User", ".local/bin"):
        p = Path(home) / sub
        if not p.exists():
            r.say(f"  > mkdir {p}")
            if not dry:
                p.mkdir(parents=True, exist_ok=True)
                os.chown(p, u.pw_uid, u.pw_gid)
                for parent in p.relative_to(home).parents:
                    if str(parent) != ".":
                        os.chown(Path(home) / parent, u.pw_uid, u.pw_gid)
    old_labkit = Path("/etc/audit/rules.d/labkit.rules")
    if old_labkit.exists():
        r.say(f"  > remove {old_labkit} (replaced by noxy.rules)")
        if not dry:
            old_labkit.rename(str(old_labkit) + ".noxy-bak")
    rules = audit_rules(home, check_exists=not dry)
    r.write(RULES_FILE, rules, 0o640)
    rc, out = r.act(["augenrules", "--load"])
    if not dry:
        _, listed = util.run(["auditctl", "-l"])
        if "-k net" not in listed and "key=net" not in listed:
            r.say("  ! connect rules with saddr_fam were not accepted; using the broader connect rule")
            r.write(RULES_FILE, rules.replace(*RULES_FALLBACK_NET), 0o640)
            r.act(["augenrules", "--load"])
            _, listed = util.run(["auditctl", "-l"])
        n = len([l for l in listed.splitlines() if l.strip() and not l.startswith("No rules")])
        r.say(f"  loaded rules: {n}")
        for key in ("exec", "net", "persist", "editor"):
            if f"-k {key}" not in listed and f"key={key}" not in listed:
                r.say(f"  ! no rules with key {key} are loaded: check `sudo auditctl -l` and /etc/audit/audit.rules")

    r.head("Audit log: readable by the noxy group, 10 x 50 MB")
    if AUDITD_CONF.exists():
        text = AUDITD_CONF.read_text()
        for k, v in (("log_group", GROUP), ("max_log_file", "50"), ("num_logs", "10"),
                     ("max_log_file_action", "ROTATE"), ("log_format", "ENRICHED")):
            text = set_conf(text, k, v)
        r.write(AUDITD_CONF, text, 0o640)
    r.act(["chgrp", GROUP, str(util.AUDIT_DIR)])
    r.act(["chmod", "0750", str(util.AUDIT_DIR)])
    logs = sorted(str(p) for p in util.AUDIT_DIR.glob("audit.log*")) if util.AUDIT_DIR.exists() else []
    if logs:
        r.act(["chgrp", GROUP] + logs)
        r.act(["chmod", "0640"] + logs)
    r.act(["systemctl", "enable", "auditd"], quiet=True)
    r.act(["auditctl", "--signal", "reload"], quiet=True)

    r.head("Capture: tcpdump on all interfaces, one file per 10 minutes, readable by the noxy group")
    cap_user = "tcpdump"
    try:
        pwd.getpwnam(cap_user)
    except KeyError:
        r.act(["useradd", "--system", "--no-create-home", "--shell", "/usr/sbin/nologin", cap_user])
    for old in ("labcap.service",):
        if Path(f"/etc/systemd/system/{old}").exists():
            r.act(["systemctl", "disable", "--now", old], quiet=True)
    r.write(CAPTURE_UNIT, CAPTURE.format(user=cap_user, group=GROUP, pcap=util.PCAP_DIR, port=port))
    r.act(["systemctl", "daemon-reload"])
    r.act(["systemctl", "reset-failed", "noxy-capture"], quiet=True)
    r.act(["systemctl", "enable", "--now", "noxy-capture"])
    if not dry:
        time.sleep(3)
        _, state = util.run(["systemctl", "is-active", "noxy-capture"])
        r.say(f"  noxy-capture: {state.strip()}")
        if state.strip() != "active":
            _, j = util.run(["journalctl", "-u", "noxy-capture", "-n", "15", "--no-pager"])
            r.say("  ! the capture did not start. Last log lines:\n" + "\n".join("    " + l for l in j.splitlines()))
            r.say("  If you see 'Permission denied' from AppArmor: sudo aa-complain /usr/bin/tcpdump, then\n"
                  "  sudo systemctl restart noxy-capture")

    r.head("Firewall snapshot for the lab page (read-only service)")
    r.write(FIREWALL_UNIT, FIREWALL.format(out=util.PCAP_DIR.parent / "firewall.txt", group=GROUP))
    r.act(["systemctl", "daemon-reload"])

    r.head("Capture control and firewall snapshot from noxy: polkit rule for the noxy group, these two services only")
    if Path("/etc/polkit-1").is_dir() and (Path("/usr/share/polkit-1/rules.d").is_dir() or POLKIT_RULE.parent.is_dir()):
        r.write(POLKIT_RULE, POLKIT, 0o644)
    else:
        r.say("  ! this polkit version has no JavaScript rules: capture start/stop from noxy will not work;\n"
              "    use sudo systemctl start|stop|restart noxy-capture in a terminal instead")

    r.say("\nDone. NEXT:\n  1. Reboot the VM (simplest), or log out completely and back in, so your account and its\n"
          "     user services pick up the noxy group.\n"
          "  2. python3 ~/noxy/noxy.py setup service   (starts noxy at login)\n"
          "  3. Optional, recommended: sudo python3 ~/noxy/noxy.py setup sysmon   (file creation anywhere)\n"
          "  4. Open http://127.0.0.1:%d/ and check the lab page." % port)


def os_release():
    out = {}
    try:
        for line in Path("/etc/os-release").read_text().splitlines():
            k, _, v = line.partition("=")
            out[k] = v.strip().strip('"')
    except OSError:
        pass
    return out


def ms_repo_sources(release, roots=("/etc/apt/sources.list", "/etc/apt/sources.list.d")):
    """apt source files that already point at Microsoft's Ubuntu repository for this release.

    REMnux ships one (for PowerShell). Adding packages-microsoft-prod on top gives the same repository two
    different signing keys, and apt then refuses to update ("Conflicting values set for option Signed-By")."""
    needle = f"packages.microsoft.com/ubuntu/{release}/prod"
    found = []
    for root in roots:
        p = Path(root)
        files = [p] if p.is_file() else (sorted(p.glob("*.list")) + sorted(p.glob("*.sources")) if p.is_dir() else [])
        for f in files:
            try:
                text = f.read_text(errors="replace")
            except OSError:
                continue
            if any(needle in line and not line.lstrip().startswith("#") for line in text.splitlines()):
                found.append(str(f))
    return found


def sysmon_setup(dry=False):
    """Sysmon for Linux for file creation, logged to /var/log/noxy/sysmon.log (group noxy)."""
    r = Runner(dry)
    if os.geteuid() != 0 and not dry:
        sys.exit("`setup sysmon` changes system settings: run it with sudo (or add --dry-run to preview).")
    try:
        grp.getgrnam(GROUP)
    except KeyError:
        if not dry:
            sys.exit("The noxy group is missing: run `sudo python3 noxy.py setup lab` first.")
    r.say("noxy setup sysmon: file-creation events from Sysmon for Linux" + (" [dry run]" if dry else ""))

    r.head("Packages: sysmonforlinux from Microsoft's repository, rsyslog")
    if shutil.which("sysmon") or Path("/opt/sysmon/sysmon").exists():
        r.say("  = sysmonforlinux installed")
    else:
        rel = os_release()
        if rel.get("ID") != "ubuntu" and "ubuntu" not in rel.get("ID_LIKE", ""):
            sys.exit(f"Ubuntu expected (found {rel.get('ID', '?')}): install sysmonforlinux by hand, then run this again.")
        release = rel.get("VERSION_ID") or "24.04"
        existing = ms_repo_sources(release)
        if existing:
            r.say(f"  = Microsoft's repository is already configured ({', '.join(existing)}): using it")
        else:
            url = MS_REPO_DEB.format(release=release)
            deb = Path("/tmp/noxy-packages-microsoft-prod.deb")
            r.say(f"  > download {url} (TLS verified)")
            if not dry:
                import ssl
                import urllib.request
                try:
                    with urllib.request.urlopen(url, timeout=60, context=ssl.create_default_context()) as resp:
                        data = resp.read(5 * 1024 * 1024)
                except OSError as e:
                    sys.exit(f"Download failed: {e}. Is the VM online (NAT adapter connected)?")
                if not data.startswith(b"!<arch>"):
                    sys.exit("The download is not a Debian package: stopping.")
                deb.write_bytes(data)
            r.act(["dpkg", "-i", str(deb)])
        rc, out = r.act(["apt-get", "update"])
        if rc != 0 and not dry and "onflicting values" in out:
            # Microsoft's repository twice (REMnux's own entry plus packages-microsoft-prod, e.g. from noxy 0.3.0):
            # drop the package's copy, keep the one that was there before.
            others = [f for f in ms_repo_sources(release) if "microsoft-prod" not in Path(f).name]
            drc, _ = util.run(["dpkg", "-s", "packages-microsoft-prod"])
            if drc == 0 and others:
                r.say("  ! apt sees Microsoft's repository twice: removing packages-microsoft-prod, keeping "
                      + ", ".join(others))
                r.act(["dpkg", "-r", "packages-microsoft-prod"])
                rc, out = r.act(["apt-get", "update"])
        if rc != 0 and not dry:
            sys.exit("apt-get update failed: fix the message above (sudo apt-get update must work), then run "
                     "`sudo python3 noxy.py setup sysmon` again.")
        rc, _ = r.act(["apt-get", "install", "-y", "sysmonforlinux"])
        if rc != 0 and not dry:
            sys.exit(f"sysmonforlinux did not install. Check that Microsoft publishes it for Ubuntu {release}.")
    if not shutil.which("rsyslogd"):
        r.act(["apt-get", "install", "-y", "rsyslog"])
    else:
        r.say("  = rsyslog installed")

    r.head("Log file: /var/log/noxy/sysmon.log, readable by the noxy group, 10 x 50 MB")
    owner = "syslog"
    try:
        pwd.getpwnam(owner)
    except KeyError:
        owner = "root"
    r.act(["install", "-d", "-o", owner, "-g", GROUP, "-m", "2750", str(SYSMON_DIR)])
    r.write(RSYSLOG_CONF, RSYSLOG.format(log=sysmon.LOG), 0o644)
    r.write(LOGROTATE_CONF, LOGROTATE.format(log=sysmon.LOG, owner=owner, group=GROUP), 0o644)
    rc, out = r.act(["rsyslogd", "-N1"])          # validate the whole rsyslog configuration before using it
    if not dry and rc != 0 and str(RSYSLOG_CONF) not in out:
        r.say("  ! rsyslog reports problems in other files (above); noxy's rule itself is fine")
    elif not dry and str(RSYSLOG_CONF) in out:
        sys.exit(f"rsyslog rejects {RSYSLOG_CONF} (output above). Nothing else was changed after it; "
                 f"remove the file with `sudo rm {RSYSLOG_CONF} && sudo systemctl restart rsyslog` and report the message.")
    r.act(["systemctl", "restart", "rsyslog"])

    r.head("Sysmon configuration: file creation only")
    r.write(sysmon.CONFIG, sysmon.CONFIG_XML, 0o644)
    exe = shutil.which("sysmon") or "/opt/sysmon/sysmon"
    installed, _ = util.run(["systemctl", "cat", "sysmon.service"])
    if dry or installed != 0:
        r.act([exe, "-accepteula", "-i", str(sysmon.CONFIG)])
    else:
        r.act(["systemctl", "start", "sysmon"])
        r.act([exe, "-c", str(sysmon.CONFIG)])            # load the new configuration into the running service
    r.act(["systemctl", "enable", "sysmon"], quiet=True)

    if not dry:
        r.head("Check: create a test file and look for it in the log")
        probe = Path(f"/tmp/noxy-sysmon-check-{int(time.time())}")
        probe.write_text("noxy\n")
        found = False
        for _ in range(10):
            time.sleep(1)
            try:
                if probe.name in sysmon.LOG.read_text(errors="replace")[-2_000_000:]:
                    found = True
                    break
            except OSError:
                pass
        probe.unlink(missing_ok=True)
        if found:
            r.say(f"  ok: the test file appeared in {sysmon.LOG}")
        else:
            r.say(f"  ! the test file did not appear in {sysmon.LOG} within 10 seconds. Check:\n"
                  "    systemctl status sysmon --no-pager\n"
                  "    sudo journalctl -u sysmon -n 30 --no-pager\n"
                  "    sudo grep -c Linux-Sysmon /var/log/syslog   (events going to syslog instead: rsyslog rule not loaded)")
    r.say("\nDone. The status page shows 'file creation (Sysmon)'; refresh a session to read the events.\n"
          "If the status page says the log is not readable, reboot once so the noxy group applies.")


def _comms():
    out = []
    for d in Path("/proc").iterdir():
        if d.name.isdigit():
            try:
                out.append((d / "comm").read_text().strip())
            except OSError:
                pass
    return out


def service(dry=False, remove=False, port=util.DEFAULT_PORT):
    r = Runner(dry)
    if os.geteuid() == 0:
        sys.exit("Run `setup service` without sudo: it is a service for your own account.")
    unit = Path.home() / ".config/systemd/user/noxy.service"
    if remove:
        r.head("Remove the noxy user service")
        r.act(["systemctl", "--user", "disable", "--now", "noxy.service"], quiet=True)
        if unit.exists():
            r.say(f"  > remove {unit}")
            if not dry:
                unit.unlink()
        r.act(["systemctl", "--user", "daemon-reload"])
        return
    r.head("noxy user service: starts at login, restarts on failure")
    python = shutil.which("python3") or sys.executable
    r.write(unit, SERVICE.format(python=python, root=util.ROOT, port=port), 0o644)
    r.act(["systemctl", "--user", "daemon-reload"])
    r.act(["systemctl", "--user", "enable", "--now", "noxy.service"])
    r.act(["systemctl", "--user", "restart", "noxy.service"], quiet=True)
    if not dry:
        time.sleep(2)
        _, state = util.run(["systemctl", "--user", "is-active", "noxy.service"])
        r.say(f"  noxy.service: {state.strip()}")
        if state.strip() != "active":
            _, j = util.run(["journalctl", "--user", "-u", "noxy.service", "-n", "20", "--no-pager"])
            r.say("  ! noxy did not start. Last log lines:\n" + "\n".join("    " + l for l in j.splitlines()))
    r.say(f"\nOpen http://127.0.0.1:{port}/ (bookmark it). Logs: journalctl --user -u noxy -f")
